// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testFuzz_property(address target, bool status) public {
        address owner = address(0);
        vm.assume(target != owner);
        vm.prank(owner);
        bool callSuccess = false;
        try c.setApprovedLogger(target, status) { callSuccess = true; } catch { callSuccess = false; }
        bool stored = c.approvedToLog(target);
        assertTrue(callSuccess && stored == status);
    }
}
